def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        use_count = {}
        current_size = 0

        def wrapped(*args, **kwargs):
            nonlocal current_size
            key = args if typed else repr(args)
            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if current_size == maxsize:
                    min_count = min(use_count.values())
                    for k, v in use_count.items():
                        if v == min_count:
                            del cache[k]
                            del use_count[k]
                            current_size -= 1
                            break
                cache[key] = result
                use_count[key] = 1
                current_size += 1
                return result
        return wrapped
